def split(s): return [x.strip() for x in s.split(",") if x.strip()]

def build():
    out = []
    for t, a, y, g, m, tr, p, cw, d in ROWS:
        out.append({
            "title": t,
            "authors": [x.strip() for x in a.replace(" and ", ";").split(";")],
            "first_publish_year": y, "genres": split(g), "moods": split(m), "tropes": split(tr),
            "pacing": p, "content_warnings": split(cw), "description": d,
        })
    return out

if __name__ == "__main__":
    p = Path(__file__).with_name("catalog.json")
    p.write_text(json.dumps(build(), indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
    print(len(ROWS), "books ->", p)
